function getCategoryForSource(sourceKey) {
  for (const [cat, sources] of Object.entries(CATEGORIES)) {
    if (sources.includes(sourceKey)) return cat;
  }
  return null;
}

function getSourcesForCategory(categoryName) {
  return CATEGORIES[categoryName] || [];
}

function listCategories() {
  return Object.entries(CATEGORIES).map(([name, sources]) => ({
    name,
    count: sources.length,
  }));
}

module.exports = { CATEGORIES, getCategoryForSource, getSourcesForCategory, listCategories };
